/**
 * Blaze Pulse: a real-time HTTP benchmark dashboard.
 *
 * The program serves a dashboard, measures every request it handles, and
 * publishes what it measured to the dashboard over an event stream. The load
 * that is measured is generated by a separate process (`bench/load.sh`), which
 * drives `oha` or `wrk` against the `/ping` route and posts what it measured
 * back to the program.
 *
 * The state the program keeps lives in an array rather than in names of its
 * own: a name a handler captures is a copy unless it is an array or a string,
 * and the handler of a server runs on the runtime's own thread, so what it
 * writes has to be seen by the program that owns the state.
 *
 * The functions are declared before the functions that call them, which is the
 * order the compiler settles them in: a function is settled by reading its
 * body, and the body of a function that calls one settles that one first.
 */

/*
 * The module the program reads its own files with. The HTTP server is the one
 * the compiler provides, so the source names it as the global it is, and the
 * module it reads files with is required the way a program requires one.
 */
const fs = require("fs");

/** The port the dashboard is served on. */
const args = process.argv.slice(2);
const port = Number(args[0]);
const listenPort = port > 0 ? port : 8080;

/** Where the dashboard's own files are read from. */
const web = "web";

/* The slots the state is held in. */
const SERVED = 0;
const FAILED = 1;
const BYTES = 2;
const RUNNING = 3;
const WINDOW_SERVED = 4;
const WINDOW_FAILED = 5;
const WINDOW_STARTED = 6;
const LATENCY_COUNT = 7;
const LATENCY_SUM = 8;
const LATENCY_MAX = 9;
const SAMPLE_INDEX = 10;
const SAMPLE_COUNT = 11;
const LAST_PUBLISH = 12;
const REPORT_RPS = 13;
const REPORT_P50 = 14;
const REPORT_P95 = 15;
const REPORT_P99 = 16;
const REPORT_ERRORS = 17;
const REPORT_TOTAL = 18;
const REPORT_DURATION = 19;
const REPORT_MEAN = 20;
const STATE_SIZE = 24;

/** How many latency samples are kept, and how many of them are enough. */
const SAMPLE_LIMIT = 256;

/** How often a snapshot is published, in milliseconds. */
const PUBLISH_INTERVAL = 100;

const state = new Float64Array(STATE_SIZE);
const samples = new Uint32Array(SAMPLE_LIMIT);

/** The snapshot the dashboard is shown, as it was last built. */
var snapshotText = "";

/** The dashboard's own files, read once when the program starts. */
const indexHtml = `${fs.readFileSync(`${web}/index.html`, "utf8")}`;
const appJs = `${fs.readFileSync(`${web}/app.js`, "utf8")}`;
const styleCss = `${fs.readFileSync(`${web}/style.css`, "utf8")}`;

/**
 * A response the program sends: the status, the kind of the body, and the
 * body itself. The bytes it wrote are counted, because a dashboard that
 * measures a server says how much that server wrote.
 */
function send(res: any, status: number, kind, body): void {
	res.writeHead(status);
	res.setHeader("Content-Type", kind);
	res.end(body);
	state[BYTES] += body.length;
}

/** The samples, in order. An insertion sort, over a handful of samples. */
function sortSamples(count: number): void {
	for (let at = 1; at < count; at += 1) {
		const value = samples[at];
		let hole = at;
		while (hole > 0 && samples[hole - 1] > value) {
			samples[hole] = samples[hole - 1];
			hole -= 1;
		}
		samples[hole] = value;
	}
}

/**
 * The latency at a fraction of the samples, in microseconds. The samples are
 * sorted in place, which is what a percentile is: the sample at that fraction
 * of them, once they are in order.
 */
function percentile(fraction: number): number {
	const count = state[SAMPLE_COUNT];
	if (count < 1) {
		return 0;
	}
	sortSamples(count);
	const index = Math.floor(fraction * (count - 1));
	return samples[index];
}

/** How long the window of the running benchmark has been open, in milliseconds. */
function windowElapsed(): number {
	if (state[RUNNING] < 1) {
		return 0;
	}
	return performance.now() - state[WINDOW_STARTED];
}

/** The mean of the latencies the server measured, in milliseconds. */
function meanLatency(): number {
	if (state[LATENCY_COUNT] < 1) {
		return 0;
	}
	return state[LATENCY_SUM] / state[LATENCY_COUNT];
}

/**
 * The latency of one request, in microseconds, kept in the ring of samples.
 * The ring is written over and over, so what the percentiles are read of is
 * the last requests the server handled and not every request it ever handled.
 */
function recordLatency(micros: number): void {
	const index = state[SAMPLE_INDEX];
	samples[index] = micros;
	state[SAMPLE_INDEX] = index + 1 >= SAMPLE_LIMIT ? 0 : index + 1;
	if (state[SAMPLE_COUNT] < SAMPLE_LIMIT) {
		state[SAMPLE_COUNT] = state[SAMPLE_COUNT] + 1;
	}
}

/**
 * What the dashboard is shown: the counters, the latency of the requests the
 * server handled, and what the load generator measured.
 *
 * A function of a program hands back a number or a reference and not a
 * string, so the snapshot is written into a name of the program's own and
 * read from there.
 */
function buildSnapshot(): void {
	let json = `{"served":${state[SERVED]}`;
	json += `,"failed":${state[FAILED]}`;
	json += `,"bytes":${state[BYTES]}`;
	json += `,"streams":${http.sseCount()}`;
	json += `,"running":${state[RUNNING]}`;
	json += `,"windowServed":${state[WINDOW_SERVED]}`;
	json += `,"windowFailed":${state[WINDOW_FAILED]}`;
	json += `,"elapsedMs":${windowElapsed()}`;
	json += `,"latencyCount":${state[LATENCY_COUNT]}`;
	json += `,"meanMs":${meanLatency()}`;
	json += `,"maxMs":${state[LATENCY_MAX]}`;
	json += `,"p50Us":${percentile(0.5)}`;
	json += `,"p95Us":${percentile(0.95)}`;
	json += `,"p99Us":${percentile(0.99)}`;
	json += `,"reportRps":${state[REPORT_RPS]}`;
	json += `,"reportP50":${state[REPORT_P50]}`;
	json += `,"reportP95":${state[REPORT_P95]}`;
	json += `,"reportP99":${state[REPORT_P99]}`;
	json += `,"reportErrors":${state[REPORT_ERRORS]}`;
	json += `,"reportTotal":${state[REPORT_TOTAL]}`;
	json += `,"reportDurationMs":${state[REPORT_DURATION]}`;
	json += `,"reportMean":${state[REPORT_MEAN]}`;
	json += "}";
	snapshotText = json;
}

/** A snapshot, written to every event stream that is open. */
function publish(): void {
	buildSnapshot();
	http.ssePublish(snapshotText);
}

/**
 * A snapshot, if enough time has passed since the last one. A server under
 * load answers thousands of requests a second, and a snapshot for each of them
 * is a snapshot nobody can read.
 */
function publishIfDue(): void {
	const now = performance.now();
	if (now - state[LAST_PUBLISH] >= PUBLISH_INTERVAL) {
		state[LAST_PUBLISH] = now;
		publish();
	}
}

/** The window of a benchmark: what is measured from now on. */
function startWindow(): void {
	state[RUNNING] = 1;
	state[WINDOW_SERVED] = 0;
	state[WINDOW_FAILED] = 0;
	state[WINDOW_STARTED] = performance.now();
	state[REPORT_RPS] = 0;
	state[REPORT_P50] = 0;
	state[REPORT_P95] = 0;
	state[REPORT_P99] = 0;
	state[REPORT_ERRORS] = 0;
	state[REPORT_TOTAL] = 0;
	state[REPORT_DURATION] = 0;
	state[REPORT_MEAN] = 0;
}

/** The window of a benchmark, closed. */
function stopWindow(): void {
	state[RUNNING] = 0;
}

/**
 * What the load generator measured, as it posted it. The numbers are read out
 * of the JSON it sent, and a field it did not send is a zero.
 */
function recordReport(req: any): void {
	var body = "";
	body += req.text();
	const report = JSON.parse(body);
	state[REPORT_RPS] = report.rps;
	state[REPORT_P50] = report.p50;
	state[REPORT_P95] = report.p95;
	state[REPORT_P99] = report.p99;
	state[REPORT_ERRORS] = report.errors;
	state[REPORT_TOTAL] = report.total;
	state[REPORT_DURATION] = report.durationMs;
	state[REPORT_MEAN] = report.mean;
}

/**
 * The server. Every route is answered here: the dashboard's own files, the
 * event stream the dashboard listens to, the routes the load generator drives,
 * and the ping it measures.
 */
const server = http.createServer((req: any, res: any) => {
	const started = performance.now();
	const path = req.path;
	const method = req.method;
	let counted = 0;

	if (path === "/") {
		send(res, 200, "text/html; charset=utf-8", indexHtml);
	} else if (path === "/app.js") {
		send(res, 200, "text/javascript; charset=utf-8", appJs);
	} else if (path === "/style.css") {
		send(res, 200, "text/css; charset=utf-8", styleCss);
	} else if (path === "/events") {
		/* The event stream: the connection stays open, and every snapshot
		   published afterwards is written to it. */
		if (http.sseSubscribe(res) > 0) {
			publish();
		}
	} else if (path === "/api/state") {
		buildSnapshot();
		send(res, 200, "application/json; charset=utf-8", snapshotText);
	} else if (path === "/api/heartbeat") {
		/* The dashboard's own heartbeat. It keeps the event stream alive
		   while the server is idle, and it is not a request the metrics
		   count: it is the dashboard asking, not the load. */
		publish();
		send(res, 200, "text/plain; charset=utf-8", "ok\n");
	} else if (path === "/api/bench/start") {
		startWindow();
		send(res, 200, "text/plain; charset=utf-8", "started\n");
	} else if (path === "/api/bench/stop") {
		stopWindow();
		send(res, 200, "text/plain; charset=utf-8", "stopped\n");
	} else if (path === "/api/bench/result") {
		if (method === "POST") {
			recordReport(req);
			send(res, 200, "text/plain; charset=utf-8", "recorded\n");
		} else {
			send(res, 405, "text/plain; charset=utf-8", "method not allowed\n");
		}
	} else if (path === "/ping") {
		/* The route the load generator drives. */
		counted = 1;
		send(res, 200, "text/plain; charset=utf-8", "pong\n");
	} else {
		counted = 1;
		state[FAILED] += 1;
		send(res, 404, "text/plain; charset=utf-8", "not found\n");
	}

	const elapsed = performance.now() - started;
	if (counted > 0) {
		state[SERVED] += 1;
		state[WINDOW_SERVED] += 1;
		state[LATENCY_COUNT] += 1;
		state[LATENCY_SUM] += elapsed;
		if (elapsed > state[LATENCY_MAX]) {
			state[LATENCY_MAX] = elapsed;
		}
		recordLatency(Math.floor(elapsed * 1000));
	}
	publishIfDue();
});

/*
 * The message is written before the server is started, so that the source of
 * the program and the program itself say the same thing: a build checks the
 * binary against the source, and a source that says nothing while the binary
 * says something is a source that does not describe the program.
 */
console.log(`blaze pulse is serving the dashboard on http://127.0.0.1:${listenPort}/`);

server.listen(listenPort, "127.0.0.1", () => {});
